EVENTS_PART3 = {
    # INS Revolution events
    "INS_revolution_events.1.t": "[HOL.GetNameDefCap] Bergerak untuk Menumpas Republik",
    "INS_revolution_events.1.desc": "Sesuai dugaan, pemerintah Belanda bereaksi keras terhadap tuntutan kemerdekaan kita dengan mengirimkan serdadu ke [1058.GetName] dan menyebarkan propaganda anti-republik melalui media massa.",
    "INS_revolution_events.1.a": "Kita harus bertindak cepat.",
    "INS_revolution_events.2.t": "[HOL.GetNameDefCap] Meminta Bantuan Tambahan",
    "INS_revolution_events.2.desc": "[HOL.GetLeader] telah mengadakan pertemuan darurat dengan para pemimpin kita, meminta agar kita memberikan bantuan lebih lanjut dalam penaklukan kembali Hindia, bahkan hingga turut serta langsung dalam konflik. [HOL.GetLeader] menyatakan bahwa situasinya teramat genting, dan pasukan Belanda tidak mampu memukul mundur laskar milisi revolusioner. [HOL.GetLeader] berjanji jika kita membantu mereka, kita akan diberi wilayah Borneo sebagai imbalan.",
    "INS_revolution_events.2.a": "Kita lakukan demi mendapatkan Borneo.",
    "INS_revolution_events.2.b": "Kita tidak tertarik.",
    "INS_revolution_events.3.t": "[ENG.GetNameDefCap] Menyetujui Kesepakatan London-Batavia",
    "INS_revolution_events.3.desc": "[ENG.GetNameDefCap] telah sepakat untuk terjun langsung ke dalam konflik, mengirimkan beberapa divisi untuk bertempur di Batavia. Meskipun kita harus melepaskan Borneo, hal ini menggeser peluang kemenangan berpihak besar kepada kita.",
    "INS_revolution_events.3.a": "Borneo akan menjadi pengorbanan yang tak terelakkan.",
    "INS_revolution_events.4.t": "[ENG.GetNameDefCap] Menolak Kesepakatan London-Batavia",
    "INS_revolution_events.4.desc": "[ENG.GetNameDefCap] telah menolak bantuan militer lebih lanjut dalam konflik ini, kendati situasi genting dan imbalan telah ditawarkan. [ENG.GetLeader] menyatakan bahwa meski menjaga imperium kolonial kita sejalan dengan kepentingan mereka, risiko eskalasi global akibat keterlibatan langsung mereka terlampau tinggi, dan kita harus menyelesaikan masalah ini sendirian.",
    "INS_revolution_events.4.a": "Ini pertanda buruk bagi kita.",
    "INS_revolution_events.5.t": "[HOL.GetNameDefCap] Meminta Bantuan Kita",
    "INS_revolution_events.5.desc": "Kaum revolusioner di Hindia Belanda telah memproklamasikan kemerdekaan dari [HOL.GetNameDef] dan menduduki kota-kota utama. [HOL.GetLeader] telah menghubungi kita dengan mendesak, meminta agar kita membantu mereka secara militer sementara mereka mempersiapkan invasi besar.",
    "INS_revolution_events.5.a": "Jika kaum revolusioner berhasil, rakyat di koloni kita mungkin akan terinspirasi melakukan hal yang sama.",
    "INS_revolution_events.5.b": "Kita tidak tertarik ikut campur.",
    "INS_revolution_events.6.t": "[ENG.GetNameDefCap] Sepakat Membantu Kita",
    "INS_revolution_events.6.desc": "[ENG.GetNameDefCap] telah sepakat untuk mengirimkan pasukan sukarelawan dan perlengkapan militer ke [1058.GetName] guna membantu kita merebut kembali kendali atas Hindia.",
    "INS_revolution_events.6.a": "Ini akan menjadi urusan yang mudah.",
    "INS_revolution_events.7.t": "[ENG.GetNameDefCap] Menolak Membantu Kita",
    "INS_revolution_events.7.desc": "[ENG.GetNameDefCap] telah menolak membantu kita menegakkan kembali kekuasaan atas Hindia, berkeras bahwa urusan Hindia bukanlah urusan mereka kendati wilayah mereka berdekatan dengan area konflik. Kita terpaksa mempersenjatai kembali KNIL dengan kekuatan kita sendiri.",
    "INS_revolution_events.7.a": "Ini sungguh tidak dapat diterima!",
    "INS_revolution_events.8.t": "Milisi Revolusioner Merancang Perlawanan di Hindia",
    "INS_revolution_events.8.desc": "Kepolisian Kolonial kita di Hindia Timur telah menangkap dan menginterogasi beberapa anggota gerakan revolusioner yang sedang bangkit di Indonesia. Tampaknya mereka tengah berupaya membangun kekuatan militer guna mempersiapkan kampanye kemerdekaan nasional. Kita belum dapat memastikan sepenuhnya, namun mereka mungkin tengah merancang revolusi bersenjata.",
    "INS_revolution_events.8.a": "Kita harus mengawasi mereka dengan sangat waspada.",
    "INS_revolution_events.9.t": "Proklamasi Kemerdekaan Indonesia",
    "INS_revolution_events.9.desc": "Sebuah pidato dibacakan hari ini di Jawa oleh [INS.GetLeader], memproklamasikan kemerdekaan Republik Indonesia yang baru didirikan. Kendati kita tidak mengakui republik baru ini, laskar milisi mereka telah menduduki banyak wilayah dan kepolisian kita gagal menegakkan ketertiban di daerah-daerah tersebut. Jika kita tidak menyikapi situasi ini dengan serius, ini bisa meletus menjadi perang terbuka.",
    "INS_revolution_events.9.a": "Tidak bisa diterima!",
    "INS_revolution_events.9.b": "Ini tidak sepadan dengan tenaga yang keluar, jika mereka begitu menginginkan kemerdekaan, biarlah begitu.",
    "INS_revolution_events.11.t": "Pasukan Hindia Berhasil Menghentikan Serbuan Milisi",
    "INS_revolution_events.11.desc": "Sebuah satuan laskar milisi Republik telah melancarkan operasi militer untuk menduduki [?event_target:INS_temp_occupied_state.GetName]. Prajurit kita yang tangguh di Hindia berhasil memukul mundur pasukan milisi, dan kita mempertahankan kendali penuh atas wilayah tersebut.",
    "INS_revolution_events.11.a": "Satu lagi kemenangan bagi [HOL.GetNameDef].",
    "INS_revolution_events.12.t": "Laskar Milisi Berusaha Menduduki [?event_target:INS_temp_occupied_state.GetName]",
    "INS_revolution_events.12.desc": "Sebuah satuan milisi Republik telah melancarkan operasi militer untuk menduduki [?event_target:INS_temp_occupied_state.GetName]. Polisi dan prajurit kita pada akhirnya berhasil mengendalikan keadaan, namun insiden ini memicu pembangkangan di dalam [?event_target:INS_temp_occupied_state.GetName], dengan banyak warga sipil mendukung milisi dan secara terang-terangan menentang pemerintah [HOL.GetAdjective].",
    "INS_revolution_events.12.a": "Kita tidak boleh membiarkan ini bereskalasi.",
    "INS_revolution_events.14.t": "Milisi Berhasil Menduduki [?event_target:INS_temp_occupied_state.GetName]",
    "INS_revolution_events.14.desc": "Kendati segenap upaya terbaik dikerahkan Polisi Kolonial dan Serdadu kita, laskar milisi Republik telah berhasil melancarkan operasi militer dan menduduki [?event_target:INS_temp_occupied_state.GetName]. Pasukan kita terpaksa mundur dan menyatakan kegagalan memerintah wilayah tersebut akibat perlawanan sengit milisi. Jika kita terus membiarkan milisi mendesak kita, kita berisiko kehilangan koloni agung kita untuk selama-lamanya.",
    "INS_revolution_events.14.a": "Ini sungguh keterlaluan!",
    "INS_revolution_no_effect_tt": "Tidak ada pengaruh",
    "INS_revolution_events.19.t": "Perundingan Damai di Hindia",
    "INS_revolution_events.19.desc": "[HOL.GetLeader] telah dipanggil ke sebuah pertemuan bersama [INS.GetLeader] guna membahas kemungkinan persetujuan damai. [INS.GetLeader] menyatakan bahwa sudah terlampau banyak nyawa yang melayang, dan mengusulkan solusi dua negara di mana batas-batas wilayah dipertahankan seperti keadaan saat ini dengan sedikit penyesuaian, serta penghentian pertempuran secara permanen.",
    "INS_revolution_events.19.a": "Kita harus sepakat. Terlalu banyak darah telah tertumpah.",
    "INS_revolution_events.19.b": "Jika kalian begitu mendambakan damai, kalian yang harus menyerah!",
    "INS_revolution_events.20.t": "[HOL.GetNameDefCap] Menyetujui Solusi Dua Negara!",
    "INS_revolution_events.20.desc": "[INS.GetLeader] telah kembali dari pertemuannya dengan [HOL.GetLeader] membawa kabar baik. Solusi dua negara telah disepakati oleh kedua belah pihak, dan kita akan segera mengatur penarikan mundur pasukan sesuai batas-batas baru. Meskipun tiada yang gembira harus meninggalkan saudara-saudara sebangsa kita di belakang, keputusan mengakhiri pertumpahan darah pada akhirnya adalah yang terbaik.",
    "INS_revolution_events.20.a": "Pertumpahan darah akhirnya usai.",
    "INS_revolution_events.21.t": "[HOL.GetNameDefCap] Menolak Menghentikan Pertempuran",
    "INS_revolution_events.21.desc": "Pertemuan [INS.GetLeader] dengan [HOL.GetLeader] tidak berjalan sesuai rencana, dengan kedua belah pihak tampak tersulut emosi dan menolak berkompromi, mengakibatkan pertemuan diputus di tengah jalan.",
    "INS_revolution_events.21.a": "Berapa banyak lagi nyawa yang harus dikorbankan?",
    "INS_revolution_events.22.t": "[HOL.GetNameDefCap] Meminta Bantuan Kita",
    "INS_revolution_events.22.desc": "[HOL.GetLeader] telah meminta pertemuan dengan [FRA.GetLeader] di Amsterdam guna membahas situasi terkini di Hindia. Dalam pertemuan itu, [HOL.GetLeader] memaparkan bagaimana kaum revolusioner mempersenjatai milisi dengan kecepatan yang tak mampu ditandingi tentara Belanda, dan bahwa [HOL.GetNameDef] berisiko kehilangan hegemoni kolonialnya. [HOL.GetLeader.GetHeShe] memohon agar kita secara resmi bergabung ke dalam konflik di pihak Belanda, dan mengirimkan divisi ke Batavia untuk membantu merebut kembali Hindia. Sebagai imbalannya, kita akan diberikan hak atas timur laut Sumatra begitu ketertiban dipulihkan.",
    "INS_revolution_events.22.a": "Meskipun membantu akan mahal, wilayah Sumatra mungkin membuatnya sepadan.",
    "INS_revolution_events.22.b": "Ini permintaan yang berlebihan bagi kita.",
    "INS_revolution_events.23.t": "[FRA.GetNameDefCap] Sepakat Membantu Kita!",
    "INS_revolution_events.23.desc": "[FRA.GetNameDefCap] telah menyetujui seruan bantuan kita, dan telah mengirimkan banyak divisi Prancis ke Batavia untuk segera memperkuat posisi kita.",
    "INS_revolution_events.23.a": "Kini angin kemenangan berpihak pada kita.",
    "INS_revolution_events.24.t": "[FRA.GetNameDefCap] Menolak Membantu.",
    "INS_revolution_events.24.desc": "[FRA.GetNameDefCap] menolak membantu kita menghadapi revolusi, kendati situasi sangat mendesak. Kita harus segera mempersenjatai diri secara mandiri dan cepat, jika tidak kita akan segera kalah jumlah.",
    "INS_revolution_events.24.a": "Keadaan tampak kian mencemaskan.",
    "INS_revolution_events.25.t": "Berakhirnya Peperangan di Indonesia",
    "INS_revolution_events.25.desc": "Pasukan [HOL.GetAdjective] telah menghancurkan pangkalan-pangkalan milisi utama dan menggulingkan pemerintahan Republik. Para tokoh elit dan komandan Republik telah ditangkap, dan administrasi Hindia menegakkan kembali operasinya di bekas wilayah Republik. Sesuai janji atas kontribusi militer kita, wilayah yang telah disepakati resmi diserahkan kepada kita.",
    "INS_revolution_events.25.a": "Luar biasa!",
    "INS_revolution_events.26.t": "Berakhirnya Peperangan di Indonesia",
    "INS_revolution_events.26.desc": "Pasukan [HOL.GetAdjective] dan laskar milisi Republik telah bertempur jauh lebih lama daripada yang diperkirakan kedua pihak, dan [HOL.GetLeader] telah sepakat menandatangani perjanjian damai yang memberlakukan solusi dua negara. Namun, karena kita tetap memenuhi kesepakatan militer kita, [HOL.GetLeader] menegaskan bahwa kita tetap akan menerima wilayah yang telah dijanjikan.",
    "INS_revolution_events.26.a": "Perkembangan yang menarik.",
    "INS_revolution_events.27.t": "Berakhirnya Peperangan di Indonesia",
    "INS_revolution_events.27.desc": "Pasukan [HOL.GetAdjective] dan milisi Republik bertempur jauh lebih sengit dari dugaan, dan kendati ada upaya besar dari [HOL.GetNameDef] serta bantuan militer kita, banyaknya jumlah laskar milisi dan taktik gerilya mereka membuat konflik menemui jalan buntu yang sangat menguntungkan pihak Republik. Maka, [HOL.GetLeader] mengumumkan hari ini bahwa [HOL.GetLeader.GetHeShe] telah menandatangani kesepakatan damai dengan Republik memberlakukan solusi dua negara yang menguntungkan Republik. Apa yang tersisa dari Hindia hanyalah puing-puing kejayaan masa lalunya. [HOL.GetLeader] menyatakan bahwa karena konflik berakhir dengan kekalahan, beliau tidak dapat menyerahkan wilayah yang dijanjikan atas kontribusi militer kita.",
    "INS_revolution_events.27.a": "Ini kegilaan yang tak masuk akal!",
    "INS_revolution_events.28.t": "Runtuhnya Hindia Belanda",
    "INS_revolution_events.28.desc": "Kendati anggaran militer besar-besaran telah dikucurkan oleh [HOL.GetNameDef], dan bantuan langsung kita kerahkan ke medan laga, banyaknya milisi di Hindia berhasil memukul mundur pasukan kita, dan telah menduduki seluruh kota utama, menumbangkan administrasi Belanda dan memaksakan penyerahan kekuasaan.",
    "INS_revolution_events.28.a": "Tapi kita sudah dijanjikan wilayah!",
    "INS_revolution_events.29.t": "Runtuhnya Hindia Belanda",
    "INS_revolution_events.29.desc": "Kendati segala upaya terbaik telah dikerahkan, kaum revolusioner di Hindia telah menguasai kota-kota besar kita dan meruntuhkan pemerintahan kolonial dari dalam. Para jenderal kita tertawan dan jalur komunikasi kita terputus. Kita tidak punya pilihan lain selain menerima kekalahan pahit ini.",
    "INS_revolution_events.29.a": "Sebuah tragedi besar bagi bangsa kita.",
    "INS_revolution_events.30.t": "[INS.GetLeader] Mengusulkan Gencatan Senjata Lokal",
    "INS_revolution_events.30.desc": "[INS.GetLeader] telah mengusulkan gencatan senjata lokal di [FROM.GetName], berjanji menarik pasukannya dari [FROM.GetName] jika kita setuju, memungkinkan pasukan kita menegakkan kembali ketertiban di wilayah tersebut. Namun, hal ini dengan syarat kita menunda operasi militer besar untuk sementara waktu, memberi kaum revolusioner waktu untuk menyusun siasat.",
    "INS_revolution_events.30.a": "Kita terima tawaran ini.",
    "INS_revolution_events.30.b": "Kita tolak, kita akan rebut kembali [FROM.GetName] dengan kekuatan senjata!",
    "INS_revolution_events.31.t": "[HOL.GetNameDefCap] Menyetujui Gencatan Senjata di [FROM.GetName]",
    "INS_revolution_events.31.desc": "Perundingan gencatan senjata berjalan lancar, dengan [HOL.GetLeader] menyetujui syarat-syarat kita. Kita telah memerintahkan komandan milisi di [FROM.GetName] untuk segera menarik pasukannya.",
    "INS_revolution_events.31.a": "Semoga mereka memegang teguh komitmen perjanjian ini.",
    "INS_revolution_events.32.t": "[HOL.GetNameDefCap] Menolak Gencatan Senjata",
    "INS_revolution_events.32.desc": "Perundingan gencatan senjata tidak berjalan seperti yang diharapkan, dan [HOL.GetLeader] menolak menandatangani kesepakatan serta memutus perundingan sebelum kompromi dapat ditemukan.",
    "INS_revolution_events.32.a": "Ini tidak dapat diterima!",
    "INS_revolution_events.33.t": "[INS.GetNameDefCap] Meminta Mediasi",
    "INS_revolution_events.33.desc": "Kaum republikan Indonesia secara resmi meminta bantuan kita untuk menengahi penyelesaian dengan pihak Belanda. Para penasihat kita di kawasan melaporkan bahwa situasi memburuk dengan cepat, dan berlanjutnya operasi militer Belanda berisiko mendorong kaum nasionalis ke pelukan Uni Soviet. Belanda adalah sekutu berharga di Eropa, namun kita tidak dapat menutup mata terhadap realitas politik di Asia Tenggara. Jika Indonesia jatuh ke tangan komunisme karena kita berpangku tangan, itu adalah kegagalan kita.",
    "INS_revolution_events.33.a": "Kirim para mediator diplomatik.",
    "INS_revolution_events.33.b": "Kita tidak boleh mempertaruhkan hubungan baik dengan Belanda.",
    "INS_revolution_events.34.t": "[FROM.GetNameDefCap] Sepakat Memediasi",
    "INS_revolution_events.34.desc": "Washington telah sepakat untuk menjadi penengah antara pemerintah kita dan pihak Belanda. Utusan-utusan Amerika sedang dalam perjalanan, dan gencatan senjata formal akan diusulkan. Ini adalah peluang emas yang luar biasa. Dengan kekuatan terkemuka dunia mendukung perundingan, Belanda akan merasa jauh lebih sulit untuk mengulur waktu atau menggunakan kekerasan militer. Kita harus bersikap teguh di meja perundingan dan membiarkan Amerika melakukan keahlian diplomatik mereka.",
    "INS_revolution_events.34.a": "Semoga pihak Belanda dapat berpikir rasional.",
    "INS_revolution_events.35.t": "[USA.GetNameDefCap] Mengumumkan Mediasi",
    "INS_revolution_events.35.desc": "Pihak Amerika Serikat telah melibatkan diri dalam persoalan Indonesia. Washington mengklaim bertindak sebagai penengah netral, namun pesannya sudah sangat gamblang. Jika kita tidak mampu menyelesaikan konflik ini sesuai kepuasan mereka, mereka akan menggunakan pengaruh besar mereka untuk menekan kita. Para juru runding kita harus melangkah hati-hati. Niat baik Amerika bukanlah sesuatu yang sanggup kita buang percuma.",
    "INS_revolution_events.35.a": "Kita akan menyelesaikan masalah ini menurut ketentuan kita sendiri.",
    "INS_revolution_events.36.t": "[FROM.GetNameDefCap] Menolak Turun Tangan",
    "INS_revolution_events.36.desc": "Pihak Amerika telah menolak permintaan mediasi kita. Washington memilih untuk berdiri bersama sekutu Eropa mereka alih-alih mendukung perjuangan penentuan nasib sendiri bangsa kita. Kita berjuang sendirian. Ini adalah pukulan pahit, namun revolusi ini tidak dimulai karena kita mengharapkan kekuatan asing menghadiahkan kemerdekaan kepada kita.",
    "INS_revolution_events.36.a": "Kita akan memenangkan peperangan ini tanpa bantuan mereka.",
    "INS_revolution_events.37.t": "[USA.GetNameDefCap] Mengeluarkan Ultimatum",
    "INS_revolution_events.37.desc": "Pihak Amerika Serikat telah habis kesabaran. Washington telah melayangkan ultimatum yang menuntut penghentian segera seluruh operasi militer di Indonesia dan pengakuan penuh atas kedaulatan Indonesia. Ancamannya terselubung tipis. Kedudukan kita di kancah internasional tidak akan bertahan jika terjadi keretakan terbuka dengan Amerika, dan perekonomian kita tak sanggup menanggung akibatnya. Para jenderal kita berkeras operasi militer masih bisa dimenangkan, namun berapa harga yang harus dibayar?",
    "INS_revolution_events.37.a": "Kita tidak punya pilihan selain mematuhinya.",
    "INS_revolution_events.37.b": "Indonesia adalah milik kita. Kita tidak akan tunduk.",
    "INS_revolution_events.38.t": "Pihak Belanda Mengalah",
    "INS_revolution_events.38.desc": "Peperangan berakhir sudah. Pemerintah Belanda telah menerima ultimatum Amerika dan mengakui kedaulatan kita. Tiga ratus lima puluh tahun kekuasaan kolonial, berakhir bukan di medan tempur semata, melainkan di meja perundingan dengan bobot dukungan kekuatan terbesar di dunia di belakang perjuangan kita. Republik ini seutuhnya menjadi milik kita, akhirnya, merdeka sepenuhnya.",
    "INS_revolution_events.38.a": "Merdeka!",
    "INS_revolution_events.39.t": "Pihak Belanda Menolak Ultimatum",
    "INS_revolution_events.39.desc": "Di luar segala perkiraan, pihak Belanda telah menolak mentah-mentah ultimatum Amerika. Para jenderal mereka pasti percaya mereka mampu memenangkan perang ini sebelum Washington mengambil tindakan. Mereka keliru besar. Dengan Amerika kini secara terbuka berdiri di pihak kita, timbangan kekuatan telah bergeser secara menentukan. Biarkan mereka datang. Kita tidak lagi bertempur sendirian.",
    "INS_revolution_events.39.a": "Dunia berdiri tegak bersama kita.",
    "INS_revolution_events.40.t": "Pihak Belanda Menerima Syarat Kita",
    "INS_revolution_events.40.desc": "Den Haag telah menerima ultimatum kita. Pasukan Belanda di Indonesia akan menghentikan tembakan, dan kedaulatan akan dialihkan kepada Republik Indonesia. Ini adalah penyelesaian yang memuaskan dari sebuah episode yang kelam. Kepentingan kita di kawasan kini jauh lebih terlayani oleh Indonesia yang merdeka dan stabil daripada menopang proyek kolonial yang tak lagi sanggup dipertahankan Belanda.",
    "INS_revolution_events.40.a": "Hasil akhir yang sangat masuk akal.",
    "INS_revolution_events.41.t": "Pihak Belanda Membangkang kepada Kita",
    "INS_revolution_events.41.desc": "Den Haag telah menolak mentah-mentah ultimatum kita. Pasukan Belanda di Indonesia meneruskan operasi militer mereka secara terbuka menentang tuntutan Amerika. Ini adalah kekeliruan perhitungan yang luar biasa fatal. Belanda tidak dapat mengobarkan perang kolonial di Asia sembari terus bergantung pada bantuan ekonomi dan militer Amerika di Eropa. Mereka telah memaksa tangan kita bertindak.",
    "INS_revolution_events.41.a": "Biarlah demikian.",
    "INS_revolution_events.42.t": "Lemparan Dadu Terakhir",
    "INS_revolution_events.42.desc": "Laporan dari dinas intelijen kita di Batavia menggambarkan persiapan musuh yang tak menyerupai apa pun yang pernah kita saksikan dari pihak Republik. Tampaknya mereka tengah menyiapkan operasi destabilisasi besar-besaran untuk menyerbu Jawa dan melumpuhkan seluruh infrastruktur komunikasi kita, yang secara efektif menjamin kemenangan mutlak mereka. Namun, operasi ini teramat berisiko, dan mewajibkan mereka mengerahkan hampir seluruh sumber daya yang mereka miliki. Para jenderal kita memperkirakan mereka hanya mampu mempertahankan posisi ini sekitar dua tahun, dan tidak dapat dengan mudah mundur darinya. Jika kita mampu menahan mereka cukup lama, kita akan mampu meremukkan pemerintahan dan revolusi mereka bagai tomat busuk.",
    "INS_revolution_events.42.a": "Maka pertempuran penentuan pun dimulai.",
    "INS_revolution_events.43.t": "Pangkalan Milisi di [FROM.GetName] Telah Didirikan",
    "INS_revolution_events.43.desc": "Upaya kita di [FROM.GetName] telah membuahkan hasil manis, dan para pimpinan milisi lokal kita mengonfirmasi bahwa mereka telah siap bertindak ketika saatnya tiba.",
    "INS_revolution_events.43.a": "Kita harus terus melanjutkan ikhtiar kita.",

    # INS Loyalist Events
    "INS_loyalist_events.1.t": "[INS.GetLeader] Meminta Pemindahan Henri Winkelman",
    "INS_loyalist_events.1.desc": "[INS.GetLeader] telah menghubungi kita terkait konflik yang kian meluas di seluruh dunia dan posisi berbahaya yang dihadapi [INS.GetNameDef]. [INS.GetLeader] mengusulkan agar Henri Winkelman, mantan Panglima KNIL, secara resmi dipindahkan kembali ke [INS.GetNameDef] guna menjamin pertahanan koloni.",
    "INS_loyalist_events.1.a": "Kita akan mengatur pemindahannya segera.",
    "INS_loyalist_events.1.b": "Henri Winkelman sangat dibutuhkan di tanah air.",
    "INS_loyalist_events.2.t": "[HOL.GetLeader] Sepakat Memindahkan Henri Winkelman.",
    "INS_loyalist_events.2.desc": "[INS.GetLeader] telah kembali dari [HOL.GetNameDef] di mana beliau bertemu dengan [HOL.GetLeader]. Pertemuan berlangsung lancar, dengan [HOL.GetLeader] memahami situasi genting dan menyetujui pemindahan segera Winkelman. Henri Winkelman kini dalam perjalanan menuju [1058.GetName] untuk menanti perintah kita.",
    "INS_loyalist_events.2.a": "Ini akan sangat membantu pertahanan kita.",
    "INS_loyalist_events.3.t": "[HOL.GetLeader] Menolak Memindahkan Henri Winkelman",
    "INS_loyalist_events.3.desc": "[INS.GetLeader] telah kembali dari [HOL.GetNameDef] setelah bertemu dengan [HOL.GetLeader]. Sayangnya, Henri Winkelman tidak akan dikirim ke Hindia, dan kita harus mempertahankan wilayah kita tanpa kehadirannya.",
    "INS_loyalist_events.3.a": "Kita harus segera menyusun rencana baru secepatnya.",
    "INS_loyalist_events.4.t": "[FROM.GetNameDefCap] Mengusulkan Penyatuan",
    "INS_loyalist_events.4.desc": "Sebuah delegasi [FROM.GetAdjective] telah tiba di [ROOT.Capital.GetCapitalVictoryPointName] membawa usulan penyatuan. Mereka menunjuk pada warisan rumpun Melayu yang kita miliki bersama dan mencatat bahwa batas-batas antarbangsa kita ditetapkan oleh para administrator kolonial Eropa, bukan oleh rakyat yang mendiami tanah-tanah ini. Usulan ini akan membubarkan kedua pemerintahan dan membentuknya kembali sebagai satu negara kesatuan yang agung.",
    "INS_loyalist_events.4.a": "Kita menerima usulan penyatuan.",
    "INS_loyalist_events.4.b": "Kita terpaksa menolaknya.",
    "INS_loyalist_events.5.t": "[FROM.GetNameDefCap] Menerima Penyatuan",
    "INS_loyalist_events.5.desc": "Para diplomat kita telah kembali dari [FROM.Capital.GetCapitalVictoryPointName] membawa kabar yang sangat menggembirakan. Pemerintah [FROM.GetAdjective] telah menerima usulan kita, dan para pejabat mereka telah mulai menyusun pengaturan integrasi wilayah mereka ke dalam administrasi kita.",
    "INS_loyalist_events.5.a": "Bersama-sama, kita jauh lebih kuat!",
    "INS_loyalist_events.6.t": "[FROM.GetNameDefCap] Menolak Penyatuan",
    "INS_loyalist_events.6.desc": "Para diplomat kita telah kembali dari [FROM.Capital.GetCapitalVictoryPointName] dengan tangan hampa. Pemerintah [FROM.GetAdjective] enggan mempertimbangkan usulan tersebut. Sedikit alasan yang diberikan, dan delegasi kita dipulangkan hanya dengan formalitas basa-basi.",
    "INS_loyalist_events.6.a": "Kerugian bagi mereka.",
    "INS_loyalist_events.7.t": "[FROM.GetNameDefCap] Menuntut Referendum di [MAL.GetName]",
    "INS_loyalist_events.7.desc": "[FROM.GetNameDefCap] telah meminta secara resmi agar kita mengizinkan digelarnya referendum di [MAL.GetName] mengenai persoalan penyatuan dengan negara mereka. Duta besar mereka berterus terang mengenai hasil yang kemungkinan besar terjadi, menyatakan bahwa bangsa Melayu di kedua sisi perbatasan menganggap diri mereka satu bangsa. Mengizinkan pemungutan suara ini hampir pasti berarti kehilangan [MAL.GetName].",
    "INS_loyalist_events.7.a": "Biarkan rakyat menentukan nasibnya sendiri.",
    "INS_loyalist_events.7.b": "Kita tidak akan mengizinkannya.",
    "INS_loyalist_events.8.t": "[FROM.GetNameDefCap] Menyetujui Referendum Penyatuan",
    "INS_loyalist_events.8.desc": "Tuan kolonial kita telah memberikan izin kepada [FROM.FROM.GetNameDef] untuk menggelar referendum di negeri kita. Para juru kampanye [FROM.FROM.GetAdjective] telah berdatangan dalam jumlah besar, dan pemungutan suara akan dimulai dalam waktu sebulan. Pertanyaan yang diajukan kepada rakyat kita sangat sederhana: Apakah kita ingin bergabung dengan [FROM.FROM.GetNameDef], atau kita ingin tetap seperti keadaan sekarang?",
    "INS_loyalist_events.8.a": "Kita akan bergabung dengan mereka.",
    "INS_loyalist_events.8.b": "Kita lebih memilih bertahan.",
    "INS_loyalist_events.9.t": "[FROM.GetNameDefCap] Memilih Menentang Penyatuan",
    "INS_loyalist_events.9.desc": "Referendum di [FROM.GetName] telah usai. Rakyat [FROM.GetAdjective] telah memilih untuk tetap berada di bawah administrasi kita. Para juru kampanye [FROM.FROM.GetAdjective] telah bertolak kembali.",
    "INS_loyalist_events.9.a": "Sesuai dugaan.",
    "INS_loyalist_events.10.t": "[FROM.GetNameDefCap] Memilih untuk Bersatu",
    "INS_loyalist_events.10.desc": "Referendum di [FROM.GetName] telah tuntas dengan suara mayoritas mutlak mendukung penyatuan bersama [FROM.FROM.GetNameDef]. Para administrator kita di kawasan melaporkan bahwa hasil ini telah diperkirakan sebelumnya. Kita berkewajiban untuk menghormatinya.",
    "INS_loyalist_events.10.a": "Kita telah memberikan janji kita.",
    "INS_loyalist_events.11.t": "Referendum Malaya Berhasil",
    "INS_loyalist_events.11.desc": "Rakyat [MAL.GetName] telah memilih untuk bersatu dengan bangsa kita. Para pejabat [MAL.GetAdjective] tengah bekerja sama dengan administrasi kita untuk memulai serah terima wewenang pemerintahan. Akan ada satu batas yang lenyap dari peta dunia Melayu.",
    "INS_loyalist_events.11.a": "Selamat datang kembali ke pangkuan ibu pertiwi.",
    "INS_loyalist_events.12.t": "Penyatuan Malaya Ditolak",
    "INS_loyalist_events.12.desc": "Usulan kita untuk penyatuan dengan [MAL.GetName] telah ditolak. Pemerintah [MAL.GetAdjective], atau para penguasa di atas mereka, telah memutuskan untuk menolaknya. Kita harus meninjau kembali perkara ini pada saat yang lebih tepat.",
    "INS_loyalist_events.12.a": "Kita tidak akan melupakan penolakan ini.",
    "INS_loyalist_events.13.t": "[FROM.GetNameDefCap] Mengusulkan Kompromi atas Singapura",
    "INS_loyalist_events.13.desc": "Pemerintah [FROM.GetAdjective] telah mendekati kita membawa usulan kompromi mengenai Singapura. Mereka menuntut kedaulatan atas pulau tersebut, merujuk kedudukannya di jantung dunia Melayu. Sebagai imbalannya, mereka siap menjamin akses berkelanjutan kita ke pelabuhan, pangkalan militernya, serta seluruh hak konsesi sumber daya yang saat ini berlaku.",
    "INS_loyalist_events.13.a": "Sebuah kesepakatan yang adil.",
    "INS_loyalist_events.13.b": "Singapura tidak dijual.",
    "INS_loyalist_events.14.t": "Kompromi Singapura Diterima",
    "INS_loyalist_events.14.desc": "Kesepakatan telah disetujui. Singapura akan diserahkan ke bawah kendali kita, sementara pihak penguasa terdahulu mempertahankan hak akses komersial dan militer ke pelabuhannya. Sang saka kita kini berkibar megah di atas salah satu pelabuhan terpenting di Asia.",
    "INS_loyalist_events.14.a": "Selat Malaka kini milik kita.",
    "INS_loyalist_events.15.t": "Kompromi Singapura Ditolak",
    "INS_loyalist_events.15.desc": "Usulan kita telah ditolak. Pihak penguasa Singapura enggan melepaskan pulau tersebut dalam kondisi apa pun. Kita telah menawarkan segalanya selain kedaulatan penuh, dan itu pun belum cukup bagi mereka.",
    "INS_loyalist_events.15.a": "Biarlah demikian.",
    "INS_loyalist_events.16.t": "[FROM.GetNameDefCap] Meminta Penyerahan Ceylon",
    "INS_loyalist_events.16.desc": "Pemerintah [FROM.GetAdjective] telah mengajukan permohonan resmi atas penyerahan Ceylon (Sri Lanka). Diplomat mereka menyinggung hubungan dagang dan pertautan etnis yang telah berlangsung berabad-abad antara pulau itu dan dunia Melayu. Klaim tersebut sejujurnya terbilang tipis, namun [FROM.GetNameDef] telah tumbuh sedemikian kuat sehingga permintaan tersebut harus dipertimbangkan secara serius.",
    "INS_loyalist_events.16.a": "Baiklah, biarkan mereka memilikinya.",
    "INS_loyalist_events.16.b": "Ceylon akan tetap berada di bawah kendali kita.",
    "INS_loyalist_events.17.t": "Ceylon Resmi Diserahkan",
    "INS_loyalist_events.17.desc": "Proses penyerahan Ceylon telah tuntas. Administrasi kita telah mulai menempatkan pejabat di pulau tersebut, dan serah terima berlangsung aman tanpa insiden. Kita kini mengukuhkan kedudukan strategis di kedua sisi selat.",
    "INS_loyalist_events.17.a": "Sempurna.",
    "INS_loyalist_events.18.t": "Permintaan Ceylon Ditolak",
    "INS_loyalist_events.18.desc": "Permintaan kita atas penyerahan Ceylon telah ditolak mentah-mentah. Penguasa saat ini tidak berniat melepaskan pulau itu, dan para diplomat kita melaporkan bahwa pembicaraan lebih lanjut hanya akan sia-sia.",
    "INS_loyalist_events.18.a": "Mungkin di lain kesempatan.",
    "INS_loyalist_events.19.t": "[FROM.GetNameDefCap] Menuntut Referendum di Papua",
    "INS_loyalist_events.19.desc": "[FROM.GetNameDefCap] telah menuntut agar kita mengizinkan referendum di Papua timur. Di sisi perbatasan [FROM.GetAdjective], terdapat jalan-jalan baru yang membelah rimba, klinik-klinik yang diperkuat dokter pemerintah, serta sekolah-sekolah yang mengajarkan bahasa daerah. Sementara di sisi kita, gubernur terakhir hanya mengunjungi Port Moresby dua kali dalam tiga tahun. Duta besar [FROM.GetAdjective] tidak perlu banyak berucap lebih dari fakta itu.",
    "INS_loyalist_events.19.a": "Biarkan mereka menggelar pemungutan suara.",
    "INS_loyalist_events.19.b": "Kita tidak akan mengizinkan hal ini.",
    "INS_loyalist_events.20.t": "Referendum Papua Disetujui",
    "INS_loyalist_events.20.desc": "Pihak Australia sepakat untuk menggelar referendum. Setiap distrik di Papua timur mengembalikan hasil yang serupa. Investasi nyata kita di belahan barat pulau tersebut berbicara jauh lebih lantang daripada poster kampanye mana pun.",
    "INS_loyalist_events.20.a": "Pulau itu akhirnya bersatu utuh.",
    "INS_loyalist_events.21.t": "Referendum Papua Ditolak",
    "INS_loyalist_events.21.desc": "Pihak Australia menolak. Gubernur mereka di Port Moresby mengeluarkan pernyataan yang menyebut tuntutan tersebut sebagai penghinaan terhadap kedaulatan Australia. Rakyat Papua sendiri sama sekali tidak dimintai pendapat.",
    "INS_loyalist_events.21.a": "Kita akan mengingat penolakan ini.",
    "INS_loyalist_events.22.t": "[FROM.GetNameDefCap] Menuntut Penyerahan Timor Timur",
    "INS_loyalist_events.22.desc": "Pemerintah [FROM.GetAdjective] telah melayangkan tuntutan resmi atas penyerahan Timor Timur. Duta besar mereka mencatat bahwa garnisun kita di sana hanya berkekuatan kurang dari dua ratus serdadu dan Lisboa nyaris tidak mengalokasikan anggaran apa pun ke wilayah itu selama bertahun-tahun. Beliau lantas bertanya, apa sebenarnya yang sedang kita pertahankan di sana.",
    "INS_loyalist_events.22.a": "Tidak sepadan berperang demi wilayah itu.",
    "INS_loyalist_events.22.b": "Timor adalah milik kita dan akan tetap demikian.",
    "INS_loyalist_events.23.t": "Timor Timur Diserahkan",
    "INS_loyalist_events.23.desc": "Penguasa kolonial Timor Timur telah mulai menarik mundur garnisunnya dan mengemas administrasi mereka. Seluruh pulau sebentar lagi akan berada di bawah wewenang kedaulatan [INS.GetAdjective].",
    "INS_loyalist_events.23.a": "Sebagaimana mestinya.",
    "INS_loyalist_events.24.t": "Tuntutan atas Timor Timur Ditolak",
    "INS_loyalist_events.24.desc": "Gubernur kolonial di Dili secara pribadi menulis surat penolakan atas tuntutan kita, menegaskan bahwa Timor Timur tetaplah wilayah kedaulatan pemerintahnya. Staf umum militer kita telah menyusun rencana darurat seandainya kabinet hendak menindaklanjuti persoalan ini lebih jauh.",
    "INS_loyalist_events.24.a": "Mulai persiapan militer.",
    "INS_loyalist_events.25.t": "[FROM.GetNameDefCap] Mengusulkan Penyatuan",
    "INS_loyalist_events.25.desc": "Sebuah delegasi [FROM.GetAdjective] telah tiba membawa usulan penyatuan dua republik kita. Mereka berpendapat bahwa rakyat kita berbagi akar rumpun Austronesia yang jauh lebih purba daripada batas-batas kolonial yang memisahkan kita, dan bahwa sebuah negara tunggal yang membentang di seantero kepulauan akan menjadi kekuatan terhebat di Asia Tenggara. Menerima usulan ini berarti membubarkan pemerintahan kita dan berintegrasi ke dalam negara mereka.",
    "INS_loyalist_events.25.a": "Kita menerima penyatuan ini.",
    "INS_loyalist_events.25.b": "Kita telah berjuang terlalu keras demi republik ini.",
    "INS_loyalist_events.26.t": "[FROM.GetNameDefCap] Menerima Penyatuan",
    "INS_loyalist_events.26.desc": "Pemerintah [FROM.GetAdjective] telah menerima usulan kita. Para pejabat mereka telah berkoordinasi dengan pejabat kita untuk memulai proses integrasi. Dari Aceh hingga Luzon, dari Borneo hingga Mindanao, bangsa kita kini membentang di seluruh penjuru kepulauan Melayu.",
    "INS_loyalist_events.26.a": "Sebuah era baru telah bermula.",
    "INS_loyalist_events.27.t": "[FROM.GetNameDefCap] Menolak Penyatuan",
    "INS_loyalist_events.27.desc": "Pemerintah [FROM.GetAdjective] telah menolak. Perjuangan kemerdekaan mereka sendiri masih teramat baru, dan terlalu mahal, bagi mereka untuk menyerahkan kedaulatan kepada negara lain. Usulan ini pun disimpan ke dalam laci arsip.",
    "INS_loyalist_events.27.a": "Sungguh disayangkan.",
    "INS_loyalist_events.28.t": "[FROM.GetNameDefCap] Meminta Referendum di [PHI.GetName]",
    "INS_loyalist_events.28.desc": "[FROM.GetNameDefCap] secara resmi telah meminta agar kita mengizinkan referendum di [PHI.GetName] mengenai persoalan penyatuan. Para diplomat mereka menekankan warisan leluhur Austronesia yang dimiliki kedua bangsa serta sifat semu batas-batas kolonial yang memisahkan mereka. Jika pemungutan suara berlanjut, hasilnya kemungkinan besar menguntungkan [FROM.GetNameDef].",
    "INS_loyalist_events.28.a": "Rakyat berhak menyuarakan kehendak mereka.",
    "INS_loyalist_events.28.b": "Sama sekali tidak mungkin.",
    "INS_loyalist_events.29.t": "Referendum Penyatuan Disetujui",
    "INS_loyalist_events.29.desc": "[FROM.FROM.GetNameDefCap] telah mengusulkan penyatuan dua bangsa kita berdasarkan warisan bersama rumpun Austronesia. Tuan kolonial kita telah memberi izin untuk menggelar referendum atas perkara ini, dan juru kampanye [FROM.FROM.GetAdjective] telah mulai berdatangan. Hasil pemungutan suara akan menentukan apakah republik kita akan bergabung dengan [FROM.FROM.GetNameDef] atau meneruskan tatanan yang ada saat ini.",
    "INS_loyalist_events.29.a": "Ini adalah usulan yang sangat menarik.",
    "INS_loyalist_events.29.b": "Sama sekali tidak.",
    "INS_loyalist_events.30.t": "[FROM.GetNameDefCap] Memilih Menentang Penyatuan",
    "INS_loyalist_events.30.desc": "Kotak-kotak suara telah dihitung dan para juru kampanye [FROM.FROM.GetAdjective] dipersilakan angkat kaki. Rakyat [FROM.GetAdjective] memilih untuk tetap merdeka. Kemerdekaan, tampaknya, masih sangat bermakna di [FROM.Capital.GetCapitalVictoryPointName].",
    "INS_loyalist_events.30.a": "Demikianlah akhirnya.",
    "INS_loyalist_events.31.t": "[FROM.GetNameDefCap] Memilih untuk Bersatu",
    "INS_loyalist_events.31.desc": "Kotak-kotak suara telah dihitung tuntas. Rakyat [FROM.GetAdjective] telah memilih [FROM.FROM.GetNameDef] dengan selisih suara yang sangat telak. Para administrator kita telah menerima instruksi untuk memulai proses serah terima wewenang.",
    "INS_loyalist_events.31.a": "Rakyat telah berbicara.",
    "INS_loyalist_events.32.t": "[PHI.GetNameDefCap] Memilih untuk Bersatu",
    "INS_loyalist_events.32.desc": "Referendum [PHI.GetAdjective] telah berakhir memenangkan pihak kita. Pemerintah mereka telah menerima hasilnya dan membuka kontak dengan kementerian luar negeri kita guna mengatur pengalihan kekuasaan.",
    "INS_loyalist_events.32.a": "Akhirnya kita bersatu padu.",
    "INS_loyalist_events.33.t": "[PHI.GetNameDefCap] Menolak Penyatuan",
    "INS_loyalist_events.33.desc": "Pemerintah [PHI.GetAdjective] telah menolak usulan penyatuan kita. Parlemen mereka menolaknya bahkan tanpa pembahasan tingkat kedua. Kita telah menawarkan mereka tempat terhormat di negara terhebat di Asia Tenggara, namun mereka menolaknya mentah-mentah.",
    "INS_loyalist_events.33.a": "Sebuah kemunduran kecil, tiada lebih dari itu.",
}
